package com.witchersbestiary.test;
import com.witchersbestiary.merchant.*;import com.witchersbestiary.economy.*;import com.witchersbestiary.economy.Currency;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import net.minecraft.util.math.BlockPos;
public final class MerchantTests implements FabricGameTest {
 private ArcaneMerchant merchant(TestContext c){var e=ArcaneMerchants.TYPE.create(c.getWorld());var p=c.getAbsolutePos(new BlockPos(1,2,1));e.refreshPositionAndAngles(p.getX(),p.getY(),p.getZ(),0,0);c.getWorld().spawnEntity(e);return e;}
 private net.minecraft.server.network.ServerPlayerEntity player(TestContext c,ArcaneMerchant e){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();p.refreshPositionAndAngles(e.getX()+2,e.getY(),e.getZ(),0,0);return p;}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="merchant-pay")
 public void mixedCoinsMultipleWalletsOffhandAndAtomicCapacity(TestContext c){var e=merchant(c);var p=player(c,e);var offer=e.offers().stream().filter(o->o.id.equals("witchersbestiary:necrophage_oil")).findFirst().orElseThrow();p.getInventory().setStack(0,new ItemStack(Currency.CROWN,2));var a=new ItemStack(Currency.WALLET);a.set(WalletComponents.BALANCE,20L);p.getInventory().setStack(1,a);var b=new ItemStack(Currency.WALLET);b.set(WalletComponents.BALANCE,40L);p.getInventory().offHand.set(0,b);int stock=offer.stock;c.assertTrue(MerchantTransactions.buy(p,e,offer.id)&&MerchantTransactions.balance(p)==10&&offer.stock==stock-1&&p.getInventory().count(offer.result.getItem())==1,"Mixed payment exactly52 and one output");var before=p.getInventory().writeNbt(new NbtList()).toString();c.assertTrue(!MerchantTransactions.buy(p,e,offer.id)&&before.equals(p.getInventory().writeNbt(new NbtList()).toString()),"Insufficient funds never partially charge");p.getInventory().clear();for(int i=0;i<36;i++)p.getInventory().setStack(i,new ItemStack(Items.STONE,64));var wallet=new ItemStack(Currency.WALLET);wallet.set(WalletComponents.BALANCE,100L);p.getInventory().setStack(0,wallet);before=p.getInventory().writeNbt(new NbtList()).toString();c.assertTrue(!MerchantTransactions.buy(p,e,offer.id)&&before.equals(p.getInventory().writeNbt(new NbtList()).toString())&&offer.stock==stock-1,"Full bag rollback includes money and stock");p.discard();e.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="merchant-save")
 public void offersAndVillageClaimPersistWithoutRerolls(TestContext c){var e=merchant(c);e.village("test/village/one",e.getBlockPos());var p=player(c,e);var coin=new ItemStack(Currency.CROWN,20);p.getInventory().setStack(0,coin);var offer=e.offers().getFirst();c.assertTrue(MerchantTransactions.buy(p,e,offer.id),"Buy before save");var n=new NbtCompound();e.writeCustomDataToNbt(n);var copy=ArcaneMerchants.TYPE.create(c.getWorld());copy.readCustomDataFromNbt(n);c.assertTrue(copy.mode()==ArcaneMerchant.Mode.VILLAGE&&copy.village().equals(e.village())&&copy.offers().size()==e.offers().size()&&copy.offers().getFirst().stock==offer.stock&&copy.offers().getFirst().price==offer.price,"Saved mode/price/stock, no open-time reroll");var ledger=new MerchantLedger();var claim=new MerchantLedger.Claim();claim.entity=e.getUuid();claim.attempts=2;ledger.villages.put(e.village(),claim);var restored=MerchantLedger.read(ledger.writeNbt(new NbtCompound(),c.getWorld().getRegistryManager()),c.getWorld().getRegistryManager());c.assertTrue(restored.villages.get(e.village()).entity.equals(e.getUuid()),"Durable anti-duplicate claim");p.discard();e.discard();copy.discard();c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="merchant-security")
 public void sessionReplayLastStockAndForeignPlayerAreRejected(TestContext c)throws Exception{var e=merchant(c);var a=player(c,e);var b=player(c,e);for(var p:java.util.List.of(a,b)){var wallet=new ItemStack(Currency.WALLET);wallet.set(WalletComponents.BALANCE,100L);p.getInventory().setStack(0,wallet);}var offer=e.offers().getFirst();offer.stock=1;var h=new MerchantHandler(700,a.getInventory(),e.getId());a.currentScreenHandler=h;h.sendContentUpdates();c.assertTrue(MerchantTransactions.buy(a,e,offer.id)&&!MerchantTransactions.buy(b,e,offer.id),"Last unit shared between two players, cannot duplicate");var token=MerchantHandler.class.getDeclaredField("token");token.setAccessible(true);var session=(java.util.UUID)token.get(h);var next=e.offers().get(1);long aBefore=MerchantTransactions.balance(a);int stockBefore=next.stock;var packet=new MerchantPackets.Buy(700,session,0,next.id);h.buy(a,packet);h.buy(a,packet);c.assertTrue(MerchantTransactions.balance(a)==aBefore-next.price&&next.stock==stockBefore-1,"Valid packet replay spends and delivers exactly once");long before=MerchantTransactions.balance(b);h.buy(b,new MerchantPackets.Buy(700,java.util.UUID.randomUUID(),0,offer.id));c.assertTrue(MerchantTransactions.balance(b)==before,"Foreign session cannot charge");a.refreshPositionAndAngles(e.getX()+100,e.getY(),e.getZ(),0,0);c.assertTrue(!h.canUse(a)&&!MerchantTransactions.buy(a,e,offer.id),"Distance invalidates trading");a.currentScreenHandler=a.playerScreenHandler;a.discard();b.discard();e.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="merchant-placement")
 public void boundedNaturalSurfacePlacementAndDurableClaim(TestContext c){for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),net.minecraft.block.Blocks.GRASS_BLOCK);for(int y=2;y<20;y++)c.setBlockState(new BlockPos(x,y,z),net.minecraft.block.Blocks.AIR);}var center=c.getAbsolutePos(new BlockPos(24,2,24));var w=c.getWorld();String key="test/merchant/"+center.asLong();var oldClaim=new MerchantLedger.Claim();oldClaim.attempts=12;oldClaim.searchVersion=1;MerchantLedger.get(w.getServer()).villages.put(key,oldClaim);c.assertTrue(MerchantSpawns.safe(w,center),"Natural solid surface accepted");w.setBlockState(center.down(),net.minecraft.block.Blocks.OAK_PLANKS.getDefaultState());c.assertTrue(!MerchantSpawns.safe(w,center),"Player-built surface is not a spawn site");w.setBlockState(center.down(),net.minecraft.block.Blocks.GRASS_BLOCK.getDefaultState());w.setBlockState(center,net.minecraft.block.Blocks.LAVA.getDefaultState());c.assertTrue(!MerchantSpawns.safe(w,center),"Lava and occupied space rejected");w.setBlockState(center,net.minecraft.block.Blocks.AIR.getDefaultState());c.assertTrue(MerchantSpawns.village(w,key,center),"Versioned failed-claim recovery and bounded production placement: center="+center+" surface="+w.getTopY(net.minecraft.world.Heightmap.Type.MOTION_BLOCKING_NO_LEAVES,center.getX(),center.getZ())+" below="+w.getBlockState(center.down()));var claim=MerchantLedger.get(w.getServer()).villages.get(key);var uuid=claim.entity;c.assertTrue(uuid!=null&&!MerchantSpawns.village(w,key,center),"Second visitor cannot spawn another merchant");var npc=w.getEntity(uuid);npc.discard();c.assertTrue(!MerchantSpawns.village(w,key,center)&&uuid.equals(claim.entity),"Absent/unloaded claimed entity never triggers duplicate");c.complete();}

}
